// Independent one-shot consumer of the existing real ProjectHost library, not Native/GUI evidence.
use std::{fs,path::Path};
use serde_json::{Value,json};
use sf_commands::{ApiScope,ProjectHost,ObjectSource};
use sf_domain::{ObjectId,ProjectId,Revision,ModulePackage,ModuleRef,Versioned};
fn read(p:&Path)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn ok(v:Value)->Value{assert_eq!(v["outcome"]["status"],"ok","actual Host failure: {v}");v["outcome"]["data"].clone()}
fn call(h:&mut ProjectHost,ui:&ObjectId,p:Option<&ProjectId>,op:&str,params:Value)->Value{h.dispatch(ui,serde_json::from_value(json!({"api_version":"0.1","request_id":"line-grade-standard-consumer","project_id":p,"scope":{"kind":if p.is_some(){"project"}else{"workspace"}},"operation":op,"params":params})).unwrap())}
fn strip_prefix(v:&mut Value,prefix:&str){match v {Value::String(s)=>{if let Some(rest)=s.strip_prefix(prefix){*s=rest.to_owned();}},Value::Array(a)=>for v in a{strip_prefix(v,prefix)},Value::Object(o)=>for v in o.values_mut(){strip_prefix(v,prefix)},_=>{}}}
fn main(){let root=std::env::current_dir().unwrap();let out=root.join("scenarios/媒体表现/runtime-line-grade/standard-package-fix");let registration=read(&root.join("scenarios/媒体表现/runtime-line-grade/root-registration.json"));let order=registration["register_order"].as_array().unwrap();assert_eq!(order.len(),28);
 let ui=ObjectId::try_from("line-grade-standard-ui".to_owned()).unwrap();let mut host=ProjectHost::new(ObjectId::try_from("line-grade-standard-host".to_owned()).unwrap(),ui.clone());
 for entry in order{let dir=root.join(entry["directory"].as_str().unwrap());host.register_bundled_module_directory(&dir).unwrap_or_else(|e|panic!("actual register {}: {e:?}",entry["id"]));}
 let query=call(&mut host,&ui,None,"query_module_library",json!({"category_filters":["media"],"industry":null,"product_family":null,"site_envelope":null,"source_scope":["bundled"]}));fs::write(out.join("actual-query.json"),serde_json::to_vec_pretty(&query).unwrap()).unwrap();let candidates=ok(query);assert_eq!(candidates["candidates"].as_array().unwrap().len(),28);
 let time=read(&root.join("packages/commands/tests/fixtures/production/p1-phase-calendar.json"))["project"]["time_reference"].clone();ok(call(&mut host,&ui,None,"apply_commands",json!({"base_revision":null,"commands":[{"kind":"create_project","data":{"title":"Independent line-grade registration receipt","time_reference":time,"departure":"discard_after_tasks_terminal"}}]})));
 let context=ok(call(&mut host,&ui,None,"get_context",json!({"selection":[]})));let project:ProjectId=serde_json::from_value(context["project"]["id"].clone()).unwrap();let state=ok(call(&mut host,&ui,Some(&project),"get_object",json!({"object_id":{"kind":"project","id":project},"source":{"kind":"draft"},"node_index":null})));let revision:Revision=serde_json::from_value(state["data"]["revision"].clone()).unwrap();let mut rows=vec![];let mut byte_reads=0;
 for entry in order{let dir=root.join(entry["directory"].as_str().unwrap());let wrapped:Versioned<ModulePackage>=serde_json::from_value(read(&dir.join("module.json"))).unwrap();let expected=serde_json::to_value(&wrapped.data).unwrap();let reference=ModuleRef{id:wrapped.data.definition.id.clone(),version:wrapped.data.definition.version.clone()};assert!(candidates["candidates"].as_array().unwrap().iter().any(|c|c["module_ref"]["id"]==entry["id"]&&c["module_ref"]["version"]==entry["version"]));
  let response=call(&mut host,&ui,Some(&project),"get_object",json!({"object_id":{"kind":"module","id":reference.id},"source":{"kind":"module_version","data":{"module_ref":reference}},"node_index":null}));fs::write(out.join(format!("exact-{}.json",entry["id"].as_str().unwrap())),serde_json::to_vec_pretty(&response).unwrap()).unwrap();let object=ok(response);assert_eq!(object["kind"],"module");let actual:ModulePackage=serde_json::from_value(object["data"].clone()).unwrap();assert_eq!(actual.definition.id,reference.id);assert_eq!(actual.definition.version,reference.version);
  let prefix=actual.assets[0].path.as_str().strip_suffix(wrapped.data.assets[0].path.as_str()).unwrap();let mut normalized=serde_json::to_value(&actual).unwrap();strip_prefix(&mut normalized,prefix);assert_eq!(normalized,expected,"exact payload/files/rights/dependencies differ after standard Host path relocation");
  let mut assets=vec![];for (original,relocated) in wrapped.data.assets.iter().zip(&actual.assets){let bytes=host.read_media_asset(&ui,&project,&ApiScope::Project,&revision,&ObjectSource::ModuleVersion{module_ref:reference.clone()},relocated).unwrap();assert_eq!(bytes,fs::read(dir.join(original.path.as_str())).unwrap());assets.push(json!({"original":original,"actual_host_asset":relocated,"bytes":bytes.len(),"byte_identical":true}));byte_reads+=1;}
  rows.push(json!({"id":entry["id"],"version":entry["version"],"registered":true,"queried":true,"exact_payload_files_rights_dependencies_preserved_after_host_relocation":true,"assets":assets}));
 }
 assert!(!candidates["candidates"].as_array().unwrap().iter().any(|c|c["module_ref"]["id"].as_str().unwrap().ends_with(".fit")));fs::write(out.join("actual-host-receipt.json"),serde_json::to_vec_pretty(&json!({"passed":true,"source":"Existing real sf_commands::ProjectHost / one instance / trusted directory registration then public QueryModuleLibrary and exact ModuleVersion reads + private UI byte reads","schema_version":"1.0","registered":28,"queried":28,"exact_reads":28,"actual_asset_byte_reads":byte_reads,"diagnostic_fit_registered":0,"native_launched":false,"gui_acceptance":false,"engine_rerun":false,"modules":rows})).unwrap()).unwrap();println!("Real same ProjectHost: registered28 / QueryModuleLibrary28 / exact ModuleVersion28 / byte-identical asset reads{byte_reads}; fit0; no Native/GUI/Engine rerun.");
}

